<!--vbase-->
<template>
  <div id="app">
    <prism-editor
      style="height: 65vh"
      class="special-rules-editor"
      v-model="current_model.data_mapping"
      :highlight="highlighter"
      line-numbers
    ></prism-editor>
  </div>
</template>

<script>
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { PrismEditor } from 'vue-prism-editor';
import { Prism } from 'src/utils/prism';
import 'vue-prism-editor/dist/prismeditor.min.css';
import { js as beautifyJson } from 'js-beautify';

import { useSupplierExportConfigurationStore } from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [],
  props: {
    formatCode: {
      type: Boolean,
      required: true,
    },
  },
  components: {
    PrismEditor,
  },
  data() {
    return {};
  },
  mounted: function () {
    window.pyCodeEditor = this;
  },
  watch: {
    formatCode(value) {
      if (value) {
        this.formatXmlCode();
      }
    },
  },
  methods: {
    highlighter(code) {
      return Prism.highlight(code, Prism.languages.json, 'json');
    },
    formatXmlCode() {
      try {
        const jsonString = JSON.stringify(this.current_model['data_mapping']);
        this.current_model['data_mapping'] = beautifyJson(
          this.current_model['data_mapping'],
          {
            indent_size: 4,
            space_in_empty_paren: true,
          },
        );
        this.$emit('formatComplete', false);
      } catch (err) {
        logError('Error formatting XML code:', err);
      }
    },
  },
  setup() {
    const supplier_export_config = useSupplierExportConfigurationStore();
    const { processing, current_model } = storeToRefs(supplier_export_config);

    return {
      current_model,
      processing,
    };
  },
});
</script>

