<template>
  <div class="container">
    <div class="row">
    <div class="col-3 q-pa-sm">
      <q-tab-panels v-model="ionMappingTab" animated>
        <q-tab-panel name="ion_mapping" class="q-pb-none p-16">
          <q-expansion-item
            v-model="expandedION"
            :label="$t('ion_mapping')"
            group="fieldsGroup"
            header-class="text-weight-bold rounded-borders solid-border-1px"
          >
            <div class="q-ma-md">
              <q-input
                outlined
                class="back-white"
                v-model="current_model.url"
                :label="$t('url')"
                required
              >
              </q-input>
            </div>
            <div class="q-mb-none q-mx-md">
              <q-file
                v-model="current_model.file"
                data-cy="ion-file"
                outlined
                max-files="1"
                class="back-white"
                :label="$t('ion_mapping')"
              >
                <template v-slot:prepend>
                  <q-icon name="attach_file" />
                </template>
              </q-file>
              <div
                class="row justify-end"
                v-if="
                  current_model.create_supplier_config &&
                  current_model.create_supplier_config.credentials_id
                "
              >
                <f-btn
                  appearance="tertiary"
                  :label="$t('download')"
                  @click="downloadFile('create_supplier', 'ion_mapping.json')"
                />
              </div>
            </div>
          </q-expansion-item>
        </q-tab-panel>
      </q-tab-panels>
      <q-tab-panels v-model="idmMappingTab" animated>
        <q-tab-panel name="idm_mapping" class="q-py-none px-16">
          <q-expansion-item
            expand-separator
            :label="$t('idm_mapping_label')"
            group="fieldsGroup"
            header-class="text-weight-bold rounded-borders solid-border-1px"
          >
            <div class="q-ma-md">
              <q-input
                outlined
                class="back-white"
                v-model="current_model.idm_url"
                :label="$t('url')"
                required
              >
              </q-input>
            </div>
            <div class="q-mb-none q-mx-md">
              <q-file
                v-model="current_model.idm_file"
                outlined
                max-files="1"
                class="back-white"
                :label="$t('idm_mapping_label')"
              >
                <template v-slot:prepend>
                  <q-icon name="attach_file" />
                </template>
              </q-file>
              <div
                class="row justify-end"
                v-if="
                  current_model.upload_documents_config &&
                  current_model.upload_documents_config.data_mapping
                "
              >
                <f-btn
                  appearance="tertiary"
                  :label="$t('download')"
                  @click="
                    downloadFile('upload_documents', 'idm_mapping.properties')
                  "
                />
              </div>
            </div>
          </q-expansion-item>
        </q-tab-panel>
      </q-tab-panels>
      <q-tab-panels v-model="supplierDetailsMappingTab" animated>
        <q-tab-panel name="supplier_details_mapping" class="q-pt-none p-16">
          <q-expansion-item
            expand-separator
            :label="$t('supplier_details_mapping')"
            group="fieldsGroup"
            header-class="text-weight-bold rounded-borders solid-border-1px"
          >
            <div class="q-ma-md">
              <q-input
                outlined
                class="back-white"
                v-model="supplier_details_url"
                :label="$t('url')"
                required
              >
              </q-input>
            </div>
          </q-expansion-item>
        </q-tab-panel>
      </q-tab-panels>
    </div>
    <div class="col-9">
      <q-card flat bordered class="import-container white-back">
        <q-card-section style="padding-bottom: 0px">
          <div class="row">
            <q-space />
            <f-btn
              :label="$t('use_default_template')"
              @click="submitUSeDefault()"
              class="q-ml-sm"
            />
            <f-btn
              @click="formatJson()"
              :label="$t('format_button')"
              class="q-ml-sm"
            />
            <f-btn :label="$t('save')" class="q-ml-sm" @click="submit()" />
          </div>
        </q-card-section>
        <q-card-section class="row items-center q-pb-md">
          <editor
            :formatCode="is_format_code"
            @formatComplete="afterFormatted"
          />
        </q-card-section>
      </q-card>
    </div>
  </div>
  </div>
  <Loader />
</template>
<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import { storeToRefs } from 'pinia';
import { useSupplierExportConfigurationStore } from 'src/store/main';
import editor from 'src/pages/Settings/SupplierExportConfiguration/editor.vue';
import { ApiExceptions } from 'src/exceptions';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    editor,
    Loader,
  },
  watch: {
    processing: {
      handler: function (newVal, oldVal) {
        if (newVal == true) {
          this.showLoading();
        } else {
          this.hideLoading();
        }
      },
    },
  },
  computed: {
    supplier_details_url(): any {
      return this.current_model.api_supplier_details
        ? this.current_model.api_supplier_details.url
        : '';
    },
  },
  data() {
    return {
      is_format_code: ref(false),
      ionMappingTab: ref('ion_mapping'),
      idmMappingTab: ref('idm_mapping'),
      supplierDetailsMappingTab: ref('supplier_details_mapping'),
      expandedION: ref(true),
      expandedIDM: ref(false),
    };
  },
  mounted() {
    this.init();
  },
  methods: {
    async init() {
      this.processing = true;
      try {
        await this.getSupplierExportConfig();
        this.formatJson();
      } catch (error: any) {
        const message = ApiExceptions.getErrorMessage(error);
        notify.success(message);
      } finally {
        this.processing = false;
      }
    },
    formatJson() {
      this.is_format_code = true;
    },
    afterFormatted(value: any) {
      this.is_format_code = value;
    },
    async submit() {
      this.processing = true;
      try {
        await this.submitExportConfig();
        await this.getSupplierExportConfig();
        notify.success(this.$t('MSG_SAVE'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
        this.formatJson();
      }
    },
  },
  setup() {
    const supplier_export_config = useSupplierExportConfigurationStore();
    const { processing, current_model } = storeToRefs(supplier_export_config);
    const {
      downloadFile,
      getSupplierExportConfig,
      submitExportConfig,
      submitUSeDefault,
    } = supplier_export_config;
    return {
      processing,
      current_model,
      downloadFile,
      getSupplierExportConfig,
      submitExportConfig,
      submitUSeDefault,
    };
  },
});
</script>
<style scoped>
.active {
  background-color: #d9eff8;
}
body.body--dark .active {
  color: gray !important;
}
</style>
